-- ============================================================================
-- Backfill the AASFP "6 key points" (body position / stabilization / path of
-- motion / range of motion / breathing / rhythm) for the surviving source='core'
-- exercises seeded in 0004. The key_points column was added in 0027 and only the
-- source='aasfp' rows (0028) were ever populated, so every core card rendered
-- with an empty key-points panel. 0046 already removed the 7 core rows that had
-- a richer AASFP twin; this fills the rest.
--
-- Idempotent: keyed by name + source='core', and only writes where key_points is
-- still null so a hand-edited row is never clobbered.
-- ============================================================================

update exercise_db as e set key_points = v.kp
from (values
  ('Front Squat', $j${"bodyPosition":{"en":"Bar racked across the front delts, elbows high and pointing forward, feet shoulder-width with toes slightly out, torso tall.","zh":"槓鈴架於前三角肌上，手肘高舉並指向前方，雙腳與肩同寬、腳尖微外開，上身挺直。"},"stabilization":{"en":"Brace the transverse abdominis hard, keep the chest up and elbows high so the bar cannot roll forward; chin tucked.","zh":"用力收緊腹橫肌，保持挺胸及高手肘使槓鈴不前滾；下巴微收。"},"pathOfMotion":{"en":"Hips and knees flex together; the bar travels in a vertical line over mid-foot in the sagittal plane.","zh":"髖與膝同時屈曲，槓鈴沿足中垂直線於矢狀面上下移動。"},"rangeOfMotion":{"en":"Descend until thighs reach at least parallel (depth as mobility allows); stand to full hip and knee extension without locking harshly.","zh":"下蹲至大腿最少與地面平行（視柔韌度而定）；起身至髖膝完全伸展但不硬鎖。"},"breathing":{"en":"Inhale and brace at the top, hold through the descent, exhale as you drive up.","zh":"頂部吸氣並收緊核心，下蹲時憋氣，向上發力時呼氣。"},"rhythm":{"en":"Controlled — about 3 counts down, 2 counts up.","zh":"受控節奏——約 3 拍下蹲，2 拍起身。"}}$j$::jsonb),
  ('Romanian Deadlift', $j${"bodyPosition":{"en":"Stand tall holding the bar at the hips, feet hip-width, soft knees, shoulders back, neutral spine.","zh":"直立握槓於髖前，雙腳與髖同寬，膝微屈，肩向後，脊柱中立。"},"stabilization":{"en":"Brace the core and lock the lats to keep the bar close; maintain the natural lumbar curve throughout.","zh":"收緊核心並夾緊背闊肌使槓貼近身體；全程保持腰椎自然弧度。"},"pathOfMotion":{"en":"Hinge at the hips, pushing them back as the bar slides down the thighs; minimal knee bend.","zh":"由髖關節鉸鏈，臀部向後推，槓鈴沿大腿下滑；膝關節幾乎不再彎曲。"},"rangeOfMotion":{"en":"Lower until you feel a strong hamstring stretch (about mid-shin); return by driving the hips forward to standing.","zh":"下放至膕繩肌有明顯拉伸感（約小腿中段）；以髖向前頂回到站立。"},"breathing":{"en":"Inhale at the top and brace, exhale as you stand the weight up.","zh":"頂部吸氣並收緊，起身拉起時呼氣。"},"rhythm":{"en":"Controlled — about 3 counts down, 2 counts up.","zh":"受控節奏——約 3 拍下放，2 拍拉起。"}}$j$::jsonb),
  ('Conventional Deadlift', $j${"bodyPosition":{"en":"Feet hip-width under the bar (mid-foot), shins near the bar, hips between knee and shoulder height, neutral spine, arms vertical.","zh":"雙腳與髖同寬置於槓下（足中），脛骨靠近槓，臀部介乎膝與肩之間，脊柱中立，雙臂垂直。"},"stabilization":{"en":"Pull the slack out of the bar, brace the core hard and set the lats before the bar leaves the floor.","zh":"先拉緊槓上鬆動，用力收緊核心並夾緊背闊肌，再讓槓離地。"},"pathOfMotion":{"en":"Push the floor away; the bar travels straight up over mid-foot, hips and shoulders rising together.","zh":"以腳蹬地，槓鈴沿足中直線向上，髖與肩同步上升。"},"rangeOfMotion":{"en":"Lift to full hip and knee extension standing tall; lower under control back to the floor.","zh":"拉至髖膝完全伸展、身體挺直；受控下放回到地面。"},"breathing":{"en":"Inhale and brace before the pull, exhale at lockout.","zh":"拉起前吸氣並收緊核心，鎖定時呼氣。"},"rhythm":{"en":"Controlled — about 2 counts up, 2–3 counts down.","zh":"受控節奏——約 2 拍拉起，2 至 3 拍下放。"}}$j$::jsonb),
  ('Bulgarian Split Squat', $j${"bodyPosition":{"en":"Rear foot resting on a bench, front foot far enough forward that the front shin stays near vertical at the bottom, torso slightly forward.","zh":"後腳擱於板凳，前腳踏前至底部時前脛保持接近垂直，上身輕微前傾。"},"stabilization":{"en":"Brace the core and keep the hips square; control balance through the front foot, knee tracking over the toes.","zh":"收緊核心並保持髖部方正；以前腳掌控平衡，膝蓋對準腳尖。"},"pathOfMotion":{"en":"Lower the back knee straight down toward the floor in the sagittal plane, weight on the front leg.","zh":"後膝於矢狀面垂直下降趨向地面，重量落於前腿。"},"rangeOfMotion":{"en":"Descend until the rear knee nears the floor or the front thigh is parallel; drive up through the front heel.","zh":"下降至後膝接近地面或前大腿與地面平行；以前腳跟發力起身。"},"breathing":{"en":"Inhale on the way down, exhale as you drive up.","zh":"下降時吸氣，向上發力時呼氣。"},"rhythm":{"en":"Controlled — about 2–3 counts down, 1–2 counts up.","zh":"受控節奏——約 2 至 3 拍下降，1 至 2 拍起身。"}}$j$::jsonb),
  ('Walking Lunge', $j${"bodyPosition":{"en":"Stand tall holding dumbbells at the sides, feet hip-width, eyes forward, torso upright.","zh":"直立、雙手持啞鈴於體側，雙腳與髖同寬，眼望前方，上身挺直。"},"stabilization":{"en":"Brace the core and keep the pelvis level step to step; front knee tracks over the toes.","zh":"收緊核心，每步保持骨盆水平；前膝對準腳尖。"},"pathOfMotion":{"en":"Step forward with a long stride and lower straight down, then drive forward into the next step.","zh":"以長步幅向前踏出並垂直下降，再向前蹬出邁向下一步。"},"rangeOfMotion":{"en":"Lower until the rear knee nearly touches the floor and the front thigh is parallel; rise smoothly into the next lunge.","zh":"下降至後膝幾乎觸地、前大腿與地面平行；順暢起身進入下一弓步。"},"breathing":{"en":"Inhale as you lower, exhale as you push up and forward.","zh":"下降時吸氣，蹬起前進時呼氣。"},"rhythm":{"en":"Controlled and steady — about 2 counts down, 1 count up.","zh":"受控而穩定——約 2 拍下降，1 拍起身。"}}$j$::jsonb),
  ('Goblet Squat', $j${"bodyPosition":{"en":"Hold a dumbbell vertically against the chest, elbows down, feet shoulder-width, toes slightly out, chest tall.","zh":"將啞鈴垂直抱於胸前，手肘向下，雙腳與肩同寬、腳尖微外開，挺胸。"},"stabilization":{"en":"Brace the core and keep the chest up; elbows stay inside the knees at the bottom.","zh":"收緊核心並保持挺胸；底部時手肘位於膝內側。"},"pathOfMotion":{"en":"Hips and knees flex together; weight stays over mid-foot in the sagittal plane.","zh":"髖與膝同時屈曲；重量保持於足中、於矢狀面移動。"},"rangeOfMotion":{"en":"Descend until thighs reach at least parallel; stand to full hip and knee extension.","zh":"下蹲至大腿最少與地面平行；起身至髖膝完全伸展。"},"breathing":{"en":"Inhale on the way down, exhale as you drive up.","zh":"下蹲時吸氣，向上發力時呼氣。"},"rhythm":{"en":"Controlled — about 2–3 counts down, 2 counts up.","zh":"受控節奏——約 2 至 3 拍下蹲，2 拍起身。"}}$j$::jsonb),
  ('Leg Curl', $j${"bodyPosition":{"en":"Lie or sit on the machine with the pad on the lower calves just above the heels, knees aligned with the machine pivot, hips pressed into the pad.","zh":"於器械上俯臥或坐好，墊塊置於小腿下端、腳跟上方，膝關節對齊器械轉軸，髖部貼緊墊。"},"stabilization":{"en":"Keep the hips down on the pad and the upper body still; avoid arching the lower back.","zh":"保持髖部下壓於墊上、上身穩定；避免腰部過度弓起。"},"pathOfMotion":{"en":"Flex the knees to curl the pad toward the glutes in a smooth arc.","zh":"屈膝將墊塊以平順弧線捲向臀部。"},"rangeOfMotion":{"en":"Curl as far as the knee comfortably flexes, then lower under control without letting the weight hyperextend the knee.","zh":"屈膝至舒適最大幅度，再受控還原，切勿讓重量使膝關節超伸。"},"breathing":{"en":"Exhale as you curl, inhale as you return.","zh":"捲起時呼氣，還原時吸氣。"},"rhythm":{"en":"Controlled with a slow eccentric — about 2 counts up, 3 counts down.","zh":"受控並慢速離心——約 2 拍捲起，3 拍還原。"}}$j$::jsonb),
  ('Calf Raise', $j${"bodyPosition":{"en":"Balls of the feet on the platform edge, ankles free to drop below, knees straight (or fixed if seated), torso upright.","zh":"前腳掌踏於踏板邊緣，腳踝可自由下落，膝關節伸直（坐姿則固定），上身挺直。"},"stabilization":{"en":"Brace the core and keep the knees and hips steady so the movement comes only from the ankles.","zh":"收緊核心，保持膝與髖穩定，使動作僅來自踝關節。"},"pathOfMotion":{"en":"Plantar-flex the ankles to rise straight up onto the toes, then lower the heels straight down.","zh":"踝關節蹠屈直線提踵至腳尖，再將腳跟直線下放。"},"rangeOfMotion":{"en":"Lower into a full stretch below the platform, then rise to a full contraction with a brief pause at the top.","zh":"下放至踏板以下完全伸展，再上提至完全收縮並於頂部稍作停頓。"},"breathing":{"en":"Exhale as you rise, inhale as you lower.","zh":"提踵時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 2 counts up, pause, 2–3 counts down.","zh":"受控節奏——約 2 拍上提，停頓，2 至 3 拍下放。"}}$j$::jsonb),
  ('Step-Up', $j${"bodyPosition":{"en":"Stand facing a box or bench of knee height, dumbbells at the sides, one whole foot planted on the box, torso upright.","zh":"面向與膝同高的箱或板凳，雙手持啞鈴於體側，一隻腳整個踏上箱面，上身挺直。"},"stabilization":{"en":"Brace the core and keep the pelvis level; the working knee tracks over the toes.","zh":"收緊核心並保持骨盆水平；發力腿膝蓋對準腳尖。"},"pathOfMotion":{"en":"Drive through the heel of the top foot to stand up; minimise push-off from the back foot.","zh":"以上方腳跟發力站起；盡量減少後腳借力蹬地。"},"rangeOfMotion":{"en":"Step up to full hip and knee extension on top, then lower under control back to the floor.","zh":"踏上至頂部髖膝完全伸展，再受控下放回到地面。"},"breathing":{"en":"Exhale as you step up, inhale as you lower.","zh":"踏上時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 1–2 counts up, 2 counts down.","zh":"受控節奏——約 1 至 2 拍踏上，2 拍下放。"}}$j$::jsonb),
  ('Incline Dumbbell Press', $j${"bodyPosition":{"en":"Lie back on a 30–45° incline bench, feet flat, slight arch, dumbbells over the upper chest with elbows ~90°, wrists neutral.","zh":"仰臥於 30 至 45 度斜板，雙腳平放，腰部微弓，啞鈴位於上胸上方、肘約 90 度，手腕中立。"},"stabilization":{"en":"Depress and retract the shoulder girdle, brace the core, keep the hips on the bench.","zh":"肩帶下壓並縮回，收緊核心，臀部保持貼於板凳。"},"pathOfMotion":{"en":"Press the dumbbells up and slightly together along an arc over the upper chest.","zh":"將啞鈴沿弧線於上胸上方推起並略向中靠攏。"},"rangeOfMotion":{"en":"Lower until the elbows reach about 90° (or a comfortable chest-level stretch); press to nearly straight arms without locking harshly.","zh":"下放至肘約 90 度（或舒適的胸部水平伸展）；推至手臂接近伸直但不硬鎖。"},"breathing":{"en":"Inhale as you lower, exhale as you press up.","zh":"下放時吸氣，推起時呼氣。"},"rhythm":{"en":"Controlled — about 2–3 counts down, 2 counts up.","zh":"受控節奏——約 2 至 3 拍下放，2 拍推起。"}}$j$::jsonb),
  ('Overhead Press', $j${"bodyPosition":{"en":"Stand with feet shoulder-width, bar racked at the front delts, forearms vertical, wrists stacked over elbows, glutes and core braced.","zh":"雙腳與肩同寬站立，槓鈴架於前三角肌，前臂垂直，手腕對齊手肘上方，臀部與核心收緊。"},"stabilization":{"en":"Brace the core and glutes hard, keep the ribs down to avoid over-arching the lower back.","zh":"用力收緊核心與臀部，保持肋骨下沉以免腰部過度後仰。"},"pathOfMotion":{"en":"Press the bar straight up; move the head back slightly to clear it, then under the bar at the top.","zh":"將槓鈴垂直向上推，頭部略後讓開，鎖定時再移至槓下。"},"rangeOfMotion":{"en":"Press to full overhead lockout with the bar over mid-foot; lower under control to the front delts.","zh":"推至過頭完全鎖定、槓位於足中上方；受控下放回到前三角肌。"},"breathing":{"en":"Inhale and brace at the bottom, exhale through the press.","zh":"底部吸氣並收緊核心，推起時呼氣。"},"rhythm":{"en":"Controlled — about 2 counts up, 2 counts down.","zh":"受控節奏——約 2 拍推起，2 拍下放。"}}$j$::jsonb),
  ('Dumbbell Shoulder Press', $j${"bodyPosition":{"en":"Sit or stand tall with dumbbells at shoulder height, elbows under the wrists, neutral or slightly angled grip, core braced.","zh":"坐或站直，啞鈴位於肩高，手肘在手腕下方，中立或略斜握法，核心收緊。"},"stabilization":{"en":"Pin the shoulder blades down, brace the core and keep the ribs down to protect the lower back.","zh":"沉肩固定肩胛，收緊核心並保持肋骨下沉以保護腰部。"},"pathOfMotion":{"en":"Press the dumbbells up and slightly together overhead in an arc.","zh":"將啞鈴沿弧線向上推、於頭頂略向中靠攏。"},"rangeOfMotion":{"en":"Press to nearly straight arms overhead; lower until the elbows reach about shoulder height.","zh":"推至過頭手臂接近伸直；下放至肘約與肩同高。"},"breathing":{"en":"Inhale as you lower, exhale as you press up.","zh":"下放時吸氣，推起時呼氣。"},"rhythm":{"en":"Controlled — about 2 counts up, 2 counts down.","zh":"受控節奏——約 2 拍推起，2 拍下放。"}}$j$::jsonb),
  ('Push-Up', $j${"bodyPosition":{"en":"Hands slightly wider than shoulders, body in a straight line from head to heels, hollow body, elbows tucked ~45° from the torso.","zh":"雙手略闊於肩，身體由頭到腳跟成一直線，腹部微收，手肘與身體約成 45 度。"},"stabilization":{"en":"Brace the core and squeeze the glutes so the hips do not sag or pike; shoulder blades move freely.","zh":"收緊核心與臀部使髖部不下塌或上拱；肩胛可自然活動。"},"pathOfMotion":{"en":"Lower the chest toward the floor and press straight back up; the body moves as one rigid unit.","zh":"將胸部下降趨向地面再直線推起；身體如一整體般移動。"},"rangeOfMotion":{"en":"Lower until the chest nearly touches the floor (elbows ~90°); press to nearly straight arms.","zh":"下降至胸部幾乎觸地（肘約 90 度）；推至手臂接近伸直。"},"breathing":{"en":"Inhale as you lower, exhale as you press up.","zh":"下降時吸氣，推起時呼氣。"},"rhythm":{"en":"Controlled — about 2 counts down, 1–2 counts up.","zh":"受控節奏——約 2 拍下降，1 至 2 拍推起。"}}$j$::jsonb),
  ('Dip', $j${"bodyPosition":{"en":"Support on parallel bars at arm's length, wrists under shoulders; lean forward for chest emphasis or stay upright for triceps.","zh":"於雙槓上以手臂伸直支撐，手腕在肩下；前傾偏重胸部，挺直則偏重肱三頭肌。"},"stabilization":{"en":"Depress the shoulders (avoid shrugging), brace the core and keep the legs still.","zh":"下沉肩膀（避免聳肩），收緊核心並保持雙腿穩定。"},"pathOfMotion":{"en":"Lower by bending the elbows along the torso, then press straight back up.","zh":"屈肘沿身體兩側下降，再直線推起。"},"rangeOfMotion":{"en":"Lower until the elbows reach about 90° (or a comfortable shoulder stretch); press to nearly straight arms.","zh":"下降至肘約 90 度（或舒適的肩部伸展）；推至手臂接近伸直。"},"breathing":{"en":"Inhale as you lower, exhale as you press up.","zh":"下降時吸氣，推起時呼氣。"},"rhythm":{"en":"Controlled — about 2 counts down, 1–2 counts up.","zh":"受控節奏——約 2 拍下降，1 至 2 拍推起。"}}$j$::jsonb),
  ('Lateral Raise', $j${"bodyPosition":{"en":"Stand with feet hip-width, dumbbells at the sides, slight forward lean, elbows softly bent and fixed, torso steady.","zh":"雙腳與髖同寬站立，啞鈴於體側，身體微前傾，手肘微屈並固定，上身穩定。"},"stabilization":{"en":"Depress the shoulders, brace the core, and avoid swinging or using momentum.","zh":"下沉肩膀，收緊核心，避免擺動或借力。"},"pathOfMotion":{"en":"Lead with the elbows, raising the dumbbells out to the sides in an arc in the frontal plane.","zh":"以手肘帶動，將啞鈴於額狀面沿弧線向兩側舉起。"},"rangeOfMotion":{"en":"Raise until the upper arms reach about shoulder height (no higher); lower under control.","zh":"舉至上臂約與肩同高（不再更高）；受控下放。"},"breathing":{"en":"Exhale as you raise, inhale as you lower.","zh":"舉起時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 2 counts up, 2–3 counts down.","zh":"受控節奏——約 2 拍舉起，2 至 3 拍下放。"}}$j$::jsonb),
  ('Pull-Up', $j${"bodyPosition":{"en":"Hang from the bar with a pronated grip slightly wider than shoulders, arms fully extended, shoulders active (not fully shrugged up).","zh":"以正握、略闊於肩握住單槓懸垂，手臂完全伸展，肩膀保持收緊（非完全聳起）。"},"stabilization":{"en":"Depress and retract the scapulae to start, brace the core and avoid swinging.","zh":"起始時下沉並縮回肩胛，收緊核心並避免擺盪。"},"pathOfMotion":{"en":"Drive the elbows down and back to pull the chest toward the bar in the frontal/sagittal plane.","zh":"將手肘向下向後帶動，把胸部拉向單槓。"},"rangeOfMotion":{"en":"Pull until the chin clears the bar; lower under control to a full dead hang.","zh":"拉至下巴過槓；受控下放至完全懸垂。"},"breathing":{"en":"Exhale as you pull up, inhale as you lower.","zh":"拉起時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 1–2 counts up, 2–3 counts down.","zh":"受控節奏——約 1 至 2 拍拉起，2 至 3 拍下放。"}}$j$::jsonb),
  ('Chin-Up', $j${"bodyPosition":{"en":"Hang from the bar with a supinated (palms-toward-you) grip about shoulder-width, arms fully extended, shoulders active.","zh":"以反握（掌心朝向自己）約與肩同寬握住單槓懸垂，手臂完全伸展，肩膀收緊。"},"stabilization":{"en":"Depress and retract the scapulae, brace the core and keep the body still.","zh":"下沉並縮回肩胛，收緊核心並保持身體穩定。"},"pathOfMotion":{"en":"Drive the elbows down toward the ribs to pull the chest to the bar; the biceps assist.","zh":"將手肘向下帶向肋骨，把胸部拉向單槓；肱二頭肌協助發力。"},"rangeOfMotion":{"en":"Pull until the chin clears the bar; lower under control to a full hang.","zh":"拉至下巴過槓；受控下放至完全懸垂。"},"breathing":{"en":"Exhale as you pull up, inhale as you lower.","zh":"拉起時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 1–2 counts up, 2–3 counts down.","zh":"受控節奏——約 1 至 2 拍拉起，2 至 3 拍下放。"}}$j$::jsonb),
  ('Dumbbell Row', $j${"bodyPosition":{"en":"Brace one hand and knee on a bench, opposite foot on the floor, back flat and parallel-ish to the floor, dumbbell hanging from a straight arm.","zh":"一手一膝撐於板凳，另一腳踏地，背部平直並大致與地面平行，啞鈴自伸直手臂垂下。"},"stabilization":{"en":"Keep the spine neutral and hips square; brace the core and do not rotate the torso.","zh":"保持脊柱中立、髖部方正；收緊核心，不要旋轉上身。"},"pathOfMotion":{"en":"Drive the elbow back and up, pulling the dumbbell toward the hip while retracting the shoulder blade.","zh":"將手肘向後上方帶動，把啞鈴拉向髖部並同時縮回肩胛。"},"rangeOfMotion":{"en":"Pull until the dumbbell reaches the lower ribs/hip; lower to a full stretch with the arm straight.","zh":"拉至啞鈴到達下肋／髖部；下放至手臂伸直、完全伸展。"},"breathing":{"en":"Exhale as you pull, inhale as you lower.","zh":"拉起時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 1–2 counts up, 2–3 counts down.","zh":"受控節奏——約 1 至 2 拍拉起，2 至 3 拍下放。"}}$j$::jsonb),
  ('Face Pull', $j${"bodyPosition":{"en":"Stand facing a high cable with a rope, arms extended at eye level, elbows up, feet shoulder-width, slight backward lean.","zh":"面向高位鋼線握繩，手臂於眼平高度伸出，手肘上抬，雙腳與肩同寬，身體微後傾。"},"stabilization":{"en":"Brace the core, keep the torso steady and the upper arms parallel to the floor.","zh":"收緊核心，保持上身穩定、上臂與地面平行。"},"pathOfMotion":{"en":"Pull the rope toward the forehead, flaring the elbows out and externally rotating the shoulders.","zh":"將繩拉向前額，手肘向外張開並使肩關節外旋。"},"rangeOfMotion":{"en":"Pull until the hands are beside the ears with the shoulder blades retracted; return under control to a stretch.","zh":"拉至雙手位於耳旁、肩胛縮回；受控還原至伸展位。"},"breathing":{"en":"Exhale as you pull, inhale as you return.","zh":"拉起時呼氣，還原時吸氣。"},"rhythm":{"en":"Controlled — about 2 counts in, pause, 2 counts out.","zh":"受控節奏——約 2 拍拉入，停頓，2 拍還原。"}}$j$::jsonb),
  ('Plank', $j${"bodyPosition":{"en":"Forearms under the shoulders, body in a straight line from head to heels, neck neutral, eyes down.","zh":"前臂置於肩下，身體由頭到腳跟成一直線，頸部中立，眼望下方。"},"stabilization":{"en":"Brace the abdominals, tuck the ribs and squeeze the glutes; do not let the hips sag or pike.","zh":"收緊腹肌，內收肋骨並夾緊臀部；不要讓髖部下塌或上拱。"},"pathOfMotion":{"en":"Isometric hold — no movement; maintain the rigid line throughout.","zh":"等長靜止——不做動作；全程維持身體剛性直線。"},"rangeOfMotion":{"en":"Hold the position for the prescribed time without losing alignment.","zh":"在不破壞身體排列的前提下維持規定時間。"},"breathing":{"en":"Breathe steadily and shallowly; never hold the breath.","zh":"平穩淺呼吸；切勿憋氣。"},"rhythm":{"en":"Static hold — count time, not reps.","zh":"靜態維持——以時間計，而非次數。"}}$j$::jsonb),
  ('Dead Bug', $j${"bodyPosition":{"en":"Lie supine, arms reaching toward the ceiling, hips and knees bent to 90°, lower back gently flattened to the floor.","zh":"仰臥，雙臂指向天花板，髖與膝屈曲成 90 度，腰部輕輕貼平地面。"},"stabilization":{"en":"Brace the core to keep the lower back flat throughout; only the limbs move.","zh":"收緊核心使腰部全程貼平地面；僅四肢移動。"},"pathOfMotion":{"en":"Slowly extend the opposite arm and leg toward the floor, then return and switch sides.","zh":"緩慢將對側手臂與腿伸向地面，再收回並換邊。"},"rangeOfMotion":{"en":"Lower the limbs as far as you can while keeping the back flat; stop if it arches.","zh":"在腰部保持貼地的前提下盡量下放四肢；若腰部弓起即停止。"},"breathing":{"en":"Exhale as you extend the limbs, inhale as you return.","zh":"伸展四肢時呼氣，收回時吸氣。"},"rhythm":{"en":"Slow and controlled — about 2–3 counts out, 2 counts back.","zh":"緩慢受控——約 2 至 3 拍伸出，2 拍收回。"}}$j$::jsonb),
  ('Hanging Leg Raise', $j${"bodyPosition":{"en":"Hang from a bar with arms extended and shoulders active, legs together and straight, body still.","zh":"以手臂伸展、肩膀收緊懸於單槓，雙腿併攏伸直，身體穩定。"},"stabilization":{"en":"Depress the scapulae, brace the core and avoid swinging or using momentum.","zh":"下沉肩胛，收緊核心，避免擺盪或借力。"},"pathOfMotion":{"en":"Posteriorly tilt the pelvis and raise the legs forward and up by flexing the hips and curling the pelvis.","zh":"骨盆後傾，藉屈髖及捲動骨盆將雙腿向前向上抬起。"},"rangeOfMotion":{"en":"Raise the legs to at least hip height (or higher as ability allows); lower under control without swinging.","zh":"將雙腿抬至最少髖高（能力許可可更高）；受控下放且不擺盪。"},"breathing":{"en":"Exhale as you raise the legs, inhale as you lower.","zh":"抬腿時呼氣，下放時吸氣。"},"rhythm":{"en":"Controlled — about 2 counts up, 2–3 counts down.","zh":"受控節奏——約 2 拍抬起，2 至 3 拍下放。"}}$j$::jsonb),
  ('Cable Crunch', $j${"bodyPosition":{"en":"Kneel facing the high cable holding the rope beside the head, hips fixed, slight forward hinge at the hips.","zh":"面向高位鋼線跪下，將繩握於頭側，髖部固定，髖略向前傾。"},"stabilization":{"en":"Keep the hips fixed so the movement comes from the spine, not the hips; brace the core.","zh":"固定髖部使動作來自脊柱而非髖關節；收緊核心。"},"pathOfMotion":{"en":"Crunch by rounding the spine and bringing the elbows toward the thighs in the sagittal plane.","zh":"屈曲脊柱、將手肘帶向大腿，於矢狀面捲腹。"},"rangeOfMotion":{"en":"Crunch until the upper abs are fully contracted; return under control to a stretched spine.","zh":"捲至上腹完全收縮；受控還原至脊柱伸展位。"},"breathing":{"en":"Exhale as you crunch down, inhale as you return.","zh":"捲下時呼氣，還原時吸氣。"},"rhythm":{"en":"Controlled — about 2 counts down, 2–3 counts up.","zh":"受控節奏——約 2 拍捲下，2 至 3 拍還原。"}}$j$::jsonb),
  ('Pallof Press', $j${"bodyPosition":{"en":"Stand side-on to a cable at chest height, feet shoulder-width, hands clasping the handle at the sternum, knees soft.","zh":"側身對著胸高鋼線站立，雙腳與肩同寬，雙手於胸骨前握住手柄，膝微屈。"},"stabilization":{"en":"Brace the core and glutes to resist the cable's pull — the goal is anti-rotation, keeping the torso square.","zh":"收緊核心與臀部以抵抗鋼線拉力——目標是抗旋轉，保持上身方正。"},"pathOfMotion":{"en":"Press the handle straight out from the chest to full arm extension, then return, without letting the torso twist.","zh":"將手柄自胸前直線推出至手臂伸直，再收回，全程不讓上身扭轉。"},"rangeOfMotion":{"en":"Press to full extension and hold briefly, then return the hands to the chest under control.","zh":"推至完全伸直並稍作停留，再受控將雙手收回胸前。"},"breathing":{"en":"Exhale as you press out, inhale as you return.","zh":"推出時呼氣，收回時吸氣。"},"rhythm":{"en":"Controlled — about 2 counts out, pause, 2 counts in.","zh":"受控節奏——約 2 拍推出，停頓，2 拍收回。"}}$j$::jsonb),
  ('Kettlebell Swing', $j${"bodyPosition":{"en":"Feet shoulder-width, kettlebell about a foot in front, hinge at the hips with a flat back, shoulders over the bell, arms long.","zh":"雙腳與肩同寬，壺鈴置於身前約一呎，背部平直由髖鉸鏈，肩在壺鈴上方，手臂伸長。"},"stabilization":{"en":"Brace the core and lats, keep a neutral spine; it is a hip-hinge, not a squat.","zh":"收緊核心與背闊肌，保持脊柱中立；這是髖鉸鏈而非深蹲。"},"pathOfMotion":{"en":"Hike the bell back between the legs, then snap the hips forward to drive it up to chest height; the arms just guide.","zh":"將壺鈴向後盪入雙腿之間，再爆發性向前頂髖，把壺鈴帶至胸高；手臂僅作引導。"},"rangeOfMotion":{"en":"Hinge until the forearms contact the inner thighs; stand to full hip extension with glutes squeezed at the top.","zh":"鉸鏈至前臂貼大腿內側；頂部站至髖完全伸展並夾緊臀部。"},"breathing":{"en":"Exhale forcefully at the top of the swing, inhale on the backswing.","zh":"盪至頂部時用力呼氣，向後盪時吸氣。"},"rhythm":{"en":"Explosive hip snap up, controlled hinge back — a continuous ballistic rhythm.","zh":"頂髖爆發向上、受控鉸鏈向後——連續的彈震節奏。"}}$j$::jsonb),
  ('Rowing Machine', $j${"bodyPosition":{"en":"Strapped in at the catch with shins vertical, arms straight, torso leaning slightly forward from the hips, back flat.","zh":"於起划位繫好雙腳，脛骨垂直，手臂伸直，上身由髖略向前傾，背部平直。"},"stabilization":{"en":"Brace the core and keep a neutral spine; avoid rounding the back as you drive.","zh":"收緊核心並保持脊柱中立；發力時避免拱背。"},"pathOfMotion":{"en":"Sequence the drive legs → hips → arms; reverse on the recovery as arms → hips → legs.","zh":"發力次序為腿→髖→手臂；回程則相反：手臂→髖→腿。"},"rangeOfMotion":{"en":"Drive to full leg extension with the handle to the lower ribs and a slight backward lean; recover to a full compressed catch.","zh":"發力至雙腿完全伸展、手柄拉至下肋並輕微後傾；回程至完全壓縮的起划位。"},"breathing":{"en":"Exhale on the drive, inhale on the recovery.","zh":"發力時呼氣，回程時吸氣。"},"rhythm":{"en":"Strong 1-count drive, controlled 2-count recovery.","zh":"有力的 1 拍發力，受控的 2 拍回程。"}}$j$::jsonb),
  ('Assault Bike', $j${"bodyPosition":{"en":"Sit with the saddle at hip height, back tall but relaxed, hands on the moving handles, balls of the feet on the pedals.","zh":"坐於約髖高的座墊，背部挺直而放鬆，雙手握住活動把手，前腳掌踏於踏板。"},"stabilization":{"en":"Brace the core lightly and keep the torso steady; let the limbs do the work without rocking the hips.","zh":"輕度收緊核心並保持上身穩定；以四肢發力而不晃動髖部。"},"pathOfMotion":{"en":"Drive and pull the handles while the legs pedal in a continuous push–pull cycle.","zh":"推拉把手同時雙腿踩踏，形成連續的推拉循環。"},"rangeOfMotion":{"en":"Full smooth pedal and handle strokes; no need to lock the joints at the ends.","zh":"踏板與把手完成完整而流暢的行程；末端不需鎖死關節。"},"breathing":{"en":"Breathe rhythmically with effort; keep it nasal at easy paces if possible.","zh":"配合用力有節奏地呼吸；輕鬆配速時盡量用鼻呼吸。"},"rhythm":{"en":"Sustain a steady cadence; pick up the pace for intervals.","zh":"維持穩定踏頻；間歇時提升速度。"}}$j$::jsonb),
  ('Sled Push', $j${"bodyPosition":{"en":"Grip the posts with arms extended, body at a low forward angle, head neutral, back flat.","zh":"以伸直手臂握住推柄，身體呈低前傾角度，頭部中立，背部平直。"},"stabilization":{"en":"Brace the core and keep a straight line from head to heels; do not round the back.","zh":"收緊核心，保持頭到腳跟成一直線；不要拱背。"},"pathOfMotion":{"en":"Drive the legs in short, powerful steps, pushing the sled forward in a straight line.","zh":"以短而有力的步伐蹬腿，將雪橇直線向前推。"},"rangeOfMotion":{"en":"Full leg drive on each step, extending the hip and knee behind you for the prescribed distance.","zh":"每步完成完整蹬腿，於身後伸展髖與膝，推進規定距離。"},"breathing":{"en":"Breathe steadily and forcefully with each drive; do not hold the breath.","zh":"每次蹬地穩定而用力地呼吸；切勿憋氣。"},"rhythm":{"en":"Continuous powerful steps at a steady pace.","zh":"以穩定配速持續有力地邁步。"}}$j$::jsonb),
  ('Jump Rope', $j${"bodyPosition":{"en":"Stand tall, elbows close to the sides, forearms slightly out, weight on the balls of the feet, gaze forward.","zh":"身體挺直，手肘貼近身體兩側，前臂略向外，重心置於前腳掌，目視前方。"},"stabilization":{"en":"Brace the core lightly and stay relaxed; the rope is driven by the wrists, not the arms.","zh":"輕度收緊核心並保持放鬆；以手腕而非手臂搖繩。"},"pathOfMotion":{"en":"Turn the rope with small wrist circles while performing small, low bounces off the balls of the feet.","zh":"以小幅手腕畫圈搖繩，同時以前腳掌做細小低彈跳。"},"rangeOfMotion":{"en":"Keep jumps low — just enough to clear the rope (a couple of centimetres); land softly.","zh":"跳躍保持低矮——僅足以越過繩子（約數厘米）；輕柔落地。"},"breathing":{"en":"Breathe steadily and rhythmically with the bounce.","zh":"配合彈跳穩定而有節奏地呼吸。"},"rhythm":{"en":"Light, quick, even bounces — quiet feet.","zh":"輕快而均勻的彈跳——落地無聲。"}}$j$::jsonb)
) as v(name, kp)
where e.name = v.name and e.source = 'core' and e.key_points is null;
